'use strict';
let toastTimer;
function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3300);}
function clearResult(){state.result=null;state.page=0;state.search='';state.filter=null;state.sort=null;}
function commit(newData,zh,en,cleanChange=null){const before=state.data.rows.length;state.snapshots.push({data:structuredClone(state.data),history:structuredClone(state.history),clean:structuredClone(state.clean)});if(state.snapshots.length>20)state.snapshots.shift();state.data=newData;if(cleanChange)Object.assign(state.clean,cleanChange);state.history.push({zh,en,before,after:newData.rows.length,time:new Date().toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'})});clearResult();render();toast(t('操作已应用，可撤销','Applied. You can undo this step.'));}
function fail(code){const messages={quotes:t('CSV 引号不完整，请检查文件。','Unclosed CSV quote. Check your file.'),empty:t('文件需要包含字段名和至少一行数据。','Include headers and at least one data row.'),headers:t('字段名必须非空且不能重复。','Column names must be unique and non-empty.'),width:t('部分数据行的列数与表头不一致，请检查分隔符。','Some rows have a different column count. Check the delimiter.'),jsonshape:t('JSON 必须是一个非空对象数组。','JSON must be a non-empty array of objects.'),numeric:t('此操作需要数值型字段。','This operation requires a numeric column.'),fill:t('无法得到填充值，请选择其他方法或输入有效值。','No valid fill value. Choose another method or enter a value.'),name:t('新字段名不能为空或与已有字段重复。','Use a non-empty, unique column name.'),last:t('至少保留一个字段。','Keep at least one column.'),limit:t('文件过大：最多 20 MB、50,000 行、100 列。','File limit: 20 MB, 50,000 rows and 100 columns.'),pivotlimit:t('透视表每个维度最多 50 个唯一值，请选择分类字段。','Each pivot dimension allows 50 unique values. Choose categorical columns.'),target:t('请为此操作选择一个具体字段。','Choose a specific column for this operation.')};return messages[code]||t('无法处理此内容，请检查文件格式或所选字段。','Unable to process this content. Check the file format or selected columns.');}
function modal(content){$('modal-root').innerHTML=`<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${content}</section></div>`;$('modal-root').querySelector('button,input,select')?.focus();}
function closeModal(){$('modal-root').innerHTML='';$('file-input').value='';}
function openImport(){modal(`<div class="modal-header"><h2 id="modal-title">${t('给数据一个新起点','Bring your data into focus')}</h2><button class="icon-button" data-action="modal-close" aria-label="${t('关闭','Close')}">${icon('close',19)}</button></div><p>${t('导入文件，开始属于你的分析。','Import a file to start your own analysis.')}</p><button class="drop-zone" id="drop-zone" style="width:100%" data-action="pick-file">${icon('upload',32)}<strong>${t('拖拽数据文件到这里','Drop your data file here')}</strong><small>${t('或点击选择文件 · CSV / TSV / JSON · 最大 20 MB','or click to browse · CSV / TSV / JSON · up to 20 MB')}</small></button><div class="form-two">${selectField('import-encoding',t('文件编码','Encoding'),'<option value="utf-8">UTF-8</option><option value="gb18030">GB18030 / GBK</option>')}${selectField('import-delimiter',t('CSV 分隔符','CSV delimiter'),`<option value="auto">${t('自动识别','Auto-detect')}</option><option value=",">${t('逗号','Comma')} (,)</option><option value=";">${t('分号','Semicolon')} (;)</option><option value="tab">${t('制表符','Tab')}</option>`)}</div><div class="modal-note">${icon('shield',16)}<span>${t('数据不会上传到服务器。导入将替换当前数据；如需保留，请先导出。','Data is never uploaded. Import replaces your current dataset; export first to keep it.')}</span></div><p id="import-error" class="upload-error" role="alert"></p><div class="modal-actions"><button class="btn" data-action="sample-load">${t('使用内置示例','Use sample dataset')}</button><button class="btn primary" data-action="pick-file">${icon('upload',14)}${t('选择文件','Choose file')}</button></div>`);const zone=$('drop-zone');zone.ondragover=e=>{e.preventDefault();zone.classList.add('drag')};zone.ondragleave=()=>zone.classList.remove('drag');zone.ondrop=e=>{e.preventDefault();zone.classList.remove('drag');if(e.dataTransfer.files[0])importFile(e.dataTransfer.files[0]);};}
async function importFile(file){try{if(file.size>20*1024*1024)throw Error('limit');const encoding=$('import-encoding')?.value||'utf-8',text=new TextDecoder(encoding).decode(await file.arrayBuffer());let data;const ext=file.name.split('.').at(-1).toLowerCase();if(ext==='json')data=E.parseJSON(text);else if(ext==='csv'||ext==='tsv'){let delim=$('import-delimiter')?.value||'auto';if(delim==='auto'){if(ext==='tsv')delim='\t';else{const first=text.split(/\r?\n/)[0];delim=[',',';','\t'].sort((a,b)=>first.split(b).length-first.split(a).length)[0];}}if(delim==='tab')delim='\t';data=E.parseDelimited(text,delim);}else throw Error('format');if(data.rows.length>50000||data.columns.length>100)throw Error('limit');state.data=data;state.raw=structuredClone(data);state.name=file.name;state.sample=false;state.history=[];state.snapshots=[];clearResult();state.view='overview';closeModal();render();toast(t(`已导入 ${nf(data.rows.length)} 行数据`,`Imported ${nf(data.rows.length)} rows`));}catch(e){if($('import-error'))$('import-error').textContent=fail(e.message);else toast(fail(e.message));}finally{$('file-input').value='';}}
function download(content,name,mime){const url=URL.createObjectURL(new Blob([content],{type:mime})),link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(t('导出文件已生成','Export file generated'));}
function openExport(){modal(`<div class="modal-header"><h2 id="modal-title">${t('保存你的分析结果','Save your progress')}</h2><button class="icon-button" data-action="modal-close" aria-label="${t('关闭','Close')}">${icon('close',19)}</button></div><p>${t('导出可继续使用的数据文件。','Export a data file you can keep working with.')}</p><div style="margin-top:22px">${selectField('export-scope',t('导出范围','Scope'),`<option value="all">${t('当前完整数据集','Current dataset')} (${state.data.rows.length})</option><option value="filtered">${t('筛选后的数据','Filtered rows')} (${filtered().length})</option><option value="raw">${t('原始导入数据','Original imported data')} (${state.raw.rows.length})</option>`)}${selectField('export-format',t('文件格式','Format'),'<option value="csv">CSV (UTF-8)</option><option value="json">JSON</option>')}</div><div class="modal-actions"><button class="btn" data-action="modal-close">${t('取消','Cancel')}</button><button class="btn primary" data-action="download-data">${icon('download',14)}${t('下载文件','Download file')}</button></div>`);}
function exportData(){const scope=$('export-scope').value,format=$('export-format').value,data=scope==='raw'?state.raw:state.data,rows=scope==='filtered'?filtered():data.rows;const base=state.name.replace(/\.[^.]+$/,'')+'_'+scope;download(format==='csv'?E.toCSV(rows,data.columns):JSON.stringify(rows,null,2),`${base}.${format}`,format==='csv'?'text/csv;charset=utf-8':'application/json');closeModal();}
function openCompute(){modal(`<div class="modal-header"><h2 id="modal-title">${t('创建计算列','Create a computed column')}</h2><button class="icon-button" data-action="modal-close" aria-label="${t('关闭','Close')}">${icon('close',19)}</button></div><p>${t('对两个字段或一个字段与常量进行运算。','Calculate with two columns, or a column and a constant.')}</p><div style="margin-top:22px">${inputField('compute-name',t('新字段名称','New column name'),'margin',t('例如：利润率','e.g. margin'))}${selectField('compute-a',t('左侧字段','Left column'),options(validCols(),state.data.columns.includes('profit')?'profit':validCols()[0]))}${selectField('compute-op',t('运算符','Operator'),'<option value="/">÷</option><option value="*">×</option><option value="+">+</option><option value="-">−</option>')}${inputField('compute-b',t('右侧字段名或常量','Right column name or constant'),state.data.columns.includes('revenue')?'revenue':validCols()[0]||'100',t('输入原字段名或数值','Original column name or number'))}</div><div class="modal-note">${t('缺失值与除零结果记为缺失。使用原始字段名（例如 revenue），字段名区分大小写。','Missing values and division by zero become missing. Use the original, case-sensitive column name (e.g. revenue).')}</div><p id="compute-error" class="upload-error" role="alert"></p><div class="modal-actions"><button class="btn" data-action="modal-close">${t('取消','Cancel')}</button><button class="btn primary" data-action="compute">${t('创建字段','Create column')}</button></div>`);}
function exportAnalysis(){let rows,cols;if(state.analysisTab==='describe'){cols=['statistic',...state.data.columns];rows=['count','missing','unique','sum','mean','std','min','q25','median','q75','max'].map(k=>({statistic:k,...Object.fromEntries(state.data.columns.map(c=>[c,E.describe(state.data.rows,c)[k]??null]))}));}else if(state.analysisTab==='correlation'){cols=['column',...validCols()];rows=validCols().map(a=>({column:a,...Object.fromEntries(validCols().map(b=>[b,E.correlation(state.data.rows,a,b)]))}));}else if(state.result?.kind==='group'){const r=state.result;cols=[r.key,`${r.value}_${r.agg}`,'records'];rows=r.groups.map(g=>({[cols[0]]:g.key,[cols[1]]:g.value,records:g.count}));}else if(state.result?.kind==='pivot'){const r=state.result;cols=['row_key',...r.colKeys.map(v=>E.missing(v)?'(missing)':String(v))];if(new Set(cols).size!==cols.length)cols=['row_key',...r.colKeys.map((v,i)=>`${i+1}_${E.missing(v)?'(missing)':String(v)}`)];rows=r.rowKeys.map((k,i)=>Object.fromEntries(cols.map((c,j)=>[c,j===0?k:r.matrix[i][j-1]])));}else return toast(t('先生成分析结果','Run an analysis first'));download(E.toCSV(rows,cols),`clearframe_${state.analysisTab}.csv`,'text/csv;charset=utf-8');}
function bindView(){if($('overview-metric'))$('overview-metric').onchange=e=>{state.overviewMetric=e.target.value;render()};if($('data-search'))$('data-search').oninput=e=>{state.search=e.target.value;state.page=0;$('data-table').innerHTML=dataTableContent()};if($('clean-op')){$('clean-op').onchange=()=>{state.clean.op=$('clean-op').value;updateCleanFields();};$('clean-col').onchange=()=>{state.clean.column=$('clean-col').value;};updateCleanFields();} }
function updateCleanFields(){const op=state.clean.op,c=$('clean-col'),all=c.querySelector('option[value="*"]');all.disabled=op!=='dropMissing'&&op!=='dedupe';if(all.disabled&&c.value==='*'){c.value=(['fillMean','fillMedian'].includes(op)?validCols()[0]:null)||state.data.columns[0];}c.disabled=op==='dedupe';c.parentElement.querySelector('.clean-target-note')?.remove();if(op==='dedupe'){const note=document.createElement('p');note.className='clean-target-note';note.textContent=t('整行去重会比较所有字段。保留当前字段选择，方便下一步继续使用。','Duplicate removal compares all columns. Your selected column is kept for the next operation.');c.parentElement.append(note);}state.clean.column=c.value;$('clean-param-field').innerHTML=cleanParamField();if($('clean-param'))$('clean-param').oninput=()=>{state.clean.param=$('clean-param').value;};}
function runGroup(){const key=$('group-key').value,value=$('group-val').value,agg=$('group-agg').value;if(!['count','unique'].includes(agg)&&E.type(state.data.rows,value)!=='number')throw Error('numeric');state.result={kind:'group',key,value,agg,groups:E.group(state.data.rows,key,value,agg).sort((a,b)=>(b.value??-Infinity)-(a.value??-Infinity))};$('analysis-result').innerHTML=groupResultHTML();toast(t('分组分析已更新','Grouped analysis updated'));}
function runPivot(){const row=$('pivot-row').value,col=$('pivot-col').value,value=$('pivot-val').value,agg=$('pivot-agg').value;if(!['count','unique'].includes(agg)&&E.type(state.data.rows,value)!=='number')throw Error('numeric');const normalize=v=>E.missing(v)?null:v,rowKeys=[...new Set(state.data.rows.map(r=>normalize(r[row])))],colKeys=[...new Set(state.data.rows.map(r=>normalize(r[col])))];if(rowKeys.length>50||colKeys.length>50)throw Error('pivotlimit');const buckets=new Map();state.data.rows.forEach(r=>{const k=JSON.stringify([normalize(r[row]),normalize(r[col])]);if(!buckets.has(k))buckets.set(k,[]);buckets.get(k).push(r[value]);});const matrix=rowKeys.map(a=>colKeys.map(b=>{const v=buckets.get(JSON.stringify([a,b]));return v?E.aggregate(v,agg):null;}));state.result={kind:'pivot',row,col,value,agg,rowKeys,colKeys,matrix};$('analysis-result').innerHTML=pivotResultHTML();toast(t('透视表已生成','Pivot table created'));}
function editCell(button){const idx=Number(button.dataset.edit),col=button.dataset.column;if(idx<0)return;const value=state.data.rows[idx][col];const input=document.createElement('input');input.className='cell-input';input.value=E.missing(value)?'':String(value);input.setAttribute('aria-label',t('编辑值','Edit value'));button.replaceWith(input);input.focus();input.select();let done=false;function save(){if(done)return;done=true;const next=E.infer(input.value);if(next!==value){const rows=structuredClone(state.data.rows);rows[idx][col]=next;commit({columns:[...state.data.columns],rows},inLang('zh',()=>`编辑 ${label(col)}`),inLang('en',()=>`Edit ${label(col)}`));}else $('data-table').innerHTML=dataTableContent();}input.onkeydown=e=>{if(e.key==='Enter')save();if(e.key==='Escape'){done=true;$('data-table').innerHTML=dataTableContent();}};input.onblur=save;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){state.view=b.dataset.view;state.menu=false;render();window.scrollTo(0,0);return;}if(b.dataset.tab){state.analysisTab=b.dataset.tab;render();return;}if(b.dataset.sort){const c=b.dataset.sort;state.sort={c,dir:state.sort?.c===c?-state.sort.dir:1};state.page=0;$('data-table').innerHTML=dataTableContent();return;}if(b.dataset.edit){editCell(b);return;}try{switch(b.dataset.action){case'menu':state.menu=!state.menu;document.querySelector('.sidebar').classList.toggle('open',state.menu);break;case'language':$('toast').classList.remove('show');state.lang=state.lang==='zh'?'en':'zh';localStorage.setItem('clearframe-language',state.lang);render();break;case'import':openImport();break;case'pick-file':$('file-input').click();break;case'modal-close':closeModal();break;case'sample-load':state.data=E.sample();state.raw=E.sample();state.name='随机学生学习成绩_500行.csv';state.sample=true;state.chart={type:'line',x:'测试日期',y:'数学成绩',agg:'mean',group:'month'};state.overviewMetric='数学成绩';state.history=[];state.snapshots=[];state.view='overview';clearResult();closeModal();render();toast(t('示例数据已加载','Sample data loaded'));break;case'sample-export':{const d=E.sample();download(E.toCSV(d.rows,d.columns),'随机学生学习成绩_500行.csv','text/csv;charset=utf-8');break;}case'export':openExport();break;case'download-data':exportData();break;case'filter':state.filter=[$('filter-col').value,$('filter-op').value,$('filter-value').value];state.page=0;$('data-table').innerHTML=dataTableContent();toast(t(`找到 ${nf(filtered().length)} 条记录`,`Found ${nf(filtered().length)} records`));break;case'clear-filter':state.filter=null;state.search='';state.page=0;render();break;case'keep-filter':{const rows=structuredClone(filtered());commit({rows,columns:[...state.data.columns]},'保留筛选结果','Keep filtered rows');break;}case'prev':state.page--;$('data-table').innerHTML=dataTableContent();break;case'next':state.page++;$('data-table').innerHTML=dataTableContent();break;case'clean':{const op=$('clean-op').value,c=$('clean-col').value,param=$('clean-param')?.value??'';if(c==='*'&&!['dropMissing','dedupe'].includes(op))throw Error('target');const result=E.clean(state.data.rows,state.data.columns,op,c,param);commit(result,inLang('zh',()=>`${opLabel(op)} · ${op==='dedupe'||c==='*'?'所有字段':label(c)}`),inLang('en',()=>`${opLabel(op)} · ${op==='dedupe'||c==='*'?'all columns':label(c)}`),op==='rename'?{column:param.trim(),param:''}:op==='dropColumn'?{column:result.columns[Math.min(state.data.columns.indexOf(c),result.columns.length-1)]}:null);break;}case'undo':{const last=state.snapshots.pop();if(last){state.data=last.data;state.history=last.history;if(last.clean)state.clean=last.clean;clearResult();render();toast(t('已撤销上一步','Last step undone'));}break;}case'compute-open':openCompute();break;case'compute':{try{const name=$('compute-name').value,a=$('compute-a').value,op=$('compute-op').value,bv=$('compute-b').value;if(!state.data.columns.includes(bv)&&!E.number(bv))throw Error('numeric');const result=E.compute(state.data.rows,state.data.columns,name,a,op,bv);closeModal();commit(result,`创建计算列：${name}`,`Compute column: ${name}`);}catch(err){$('compute-error').textContent=fail(err.message);}break;}case'group':runGroup();break;case'pivot':runPivot();break;case'export-analysis':exportAnalysis();break;case'draw':state.chart={type:$('chart-type').value,x:$('chart-x').value,y:$('chart-y').value,agg:$('chart-agg').value,group:$('chart-group').value};if(state.chart.type==='scatter'&&E.type(state.data.rows,state.chart.x)!=='number')throw Error('numeric');render();toast(t('图表已更新','Chart updated'));break;case'export-chart':{const svg=$('custom-chart');if(!svg)return toast(t('请先生成有效图表','Create a valid chart first'));const clone=svg.cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.querySelectorAll('text').forEach(el=>{el.setAttribute('font-family','Arial, Microsoft YaHei, sans-serif');if(!el.getAttribute('fill')&&!el.style.fill)el.setAttribute('fill','#899586')});download(new XMLSerializer().serializeToString(clone),'clearframe_chart.svg','image/svg+xml');break;}}}catch(err){toast(fail(err.message));}});
$('file-input').onchange=e=>{if(e.target.files[0])importFile(e.target.files[0]);};
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('modal-root').firstChild){const list=[...$('modal-root').querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled)')],first=list[0],last=list.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
document.addEventListener('click',e=>{if(e.target.classList.contains('overlay'))closeModal();});
document.addEventListener('pointerover',e=>{const hit=e.target.closest('[data-tip]');if(!hit)return;document.querySelector('.chart-tip')?.remove();const tip=document.createElement('div');tip.className='chart-tip';tip.textContent=hit.dataset.tip;document.body.append(tip);tip.style.left=Math.max(8,Math.min(e.clientX+13,window.innerWidth-tip.offsetWidth-10))+'px';tip.style.top=Math.max(8,e.clientY-tip.offsetHeight-12)+'px';});
document.addEventListener('pointerout',e=>{if(e.target.closest('[data-tip]'))document.querySelector('.chart-tip')?.remove();});
render();
